        let max=E::from_limbs([P-1;8]).unwrap();
        for index in 0..22 {
            for case in 0..8 {
                let alpha=match case%4 {0=>E::ZERO,1=>E::ONE,2=>max,_=>random_e(&mut state)};
                let values=core::array::from_fn(|slot|match (case+slot)%4 {0=>E::ZERO,1=>E::ONE,2=>max,_=>random_e(&mut state)});
