 let x0=qw(x.c0());let x1=qw(x.c1());let y0=qw(y.c0());let y1=qw(y.c1());
 let t=qm(x0,y0);let u=qm(x1,y1);let cross=qm(qa(x0,x1),qa(y0,y1));let r=cr([u[2],u[3]]);
