#[inline(always)]
fn opening(proof: &[u8], i: usize) -> &[u8] {
    let at = compact::OFF_OPENINGS + i * OPENING;
    &proof[at..at + OPENING]
}
#[inline(always)]
fn slot(proof: &[u8], s: usize) -> &[u8] {
